return ['domain'=>'zinn-connector','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ta_IN','project-id-version'=>'zinn-connector','pot-creation-date'=>'2026-09-08T21:12:05+00:00','po-revision-date'=>'2026-09-08T21:12:05+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Connector'=>'Zinn® Connector','https://zinndigital.com/wordpress-plugins/zinn-connector'=>'https://zinndigital.com/wordpress-plugins/zinn-connector','Connects this WordPress site to Zinn Digital® so scheduled articles can be published to it. Paste a pairing code from your Zinn® dashboard and the plugin sets up its own credential — nothing is copied by hand.'=>'கட்டுரைகளைத் திட்டமிட்டபடி வெளியிட ஏதுவாக இந்த WordPress தளத்தை Zinn Digital® உடன் இணைக்கிறது. உங்கள் Zinn® டாஷ்போர்டிலிருந்து ஒரு ஜோடி சேர்த்தல் குறியீட்டை (pairing code) ஒட்டவும், பிளக்கின் (plugin) தனக்கான நற்சான்றிதழை அமைத்துக் கொள்ளும் — எதுவும் கைமுறையாக நகலெடுக்கப்படுவதில்லை.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'சேமிக்கப்பட்டது. அதை மாற்ற புதிய மதிப்பை உள்ளிடவும்.','Filter this list…'=>'இந்த பட்டியலை வடிகட்டு…','Filter this list'=>'இந்த பட்டியலை வடிகட்டவும்','Nothing matches that filter.'=>'அந்த வடிப்பானுடன் எதுவும் பொருந்தவில்லை.','Add a row'=>'ஒரு வரியைச் சேர்','Remove this row'=>'இந்த வரிசையை அகற்று','Remove'=>'நீக்கு','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — கண்ணோட்டம்','Overview'=>'கண்ணோட்டம்','Every Zinn® plugin on this site, and whether it is working.'=>'இந்தத் தளத்தில் உள்ள ஒவ்வொரு Zinn® செருகுநிரலும், அது வேலை செய்கிறதா இல்லையா என்பதும்.','No connection is needed for this plugin.'=>'இந்த செருகுநிறைவுக்கு (plugin) இணைப்பு தேவையில்லை.','Open settings'=>'அமைப்புகளைத் திறக்கவும்','You do not have permission to change these settings.'=>'இந்த அமைப்புகளை மாற்ற உங்களுக்கு அனுமதி இல்லை.','Settings sections'=>'அமைப்புகள் பிரிவுகள்','Support'=>'ஆதரவு','Save changes'=>'மாற்றங்களைச் சேமிக்கவும்','Tools'=>'கருவிகள்','Export settings'=>'அமைப்புகளை ஏற்றுமதி செய்','Reset to defaults'=>'இயல்புநிலைகளுக்கு மீட்டமைக்க','This puts every setting on this plugin back to its default. Continue?'=>'இந்த செருகுநிரலின் ஒவ்வொரு அமைப்பையும் அதன் இயல்புநிலைக்கு மாற்றும். தொடரவா?','Diagnostics for support'=>'ஆதரவிற்கான கண்டறிதல்கள்','Import a settings file'=>'அமைப்புகள் கோப்பை இறக்குமதி செய்','Import'=>'இறக்குமதி','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'ஏற்றுமதி செய்யப்பட்ட கோப்புகளில் கடவுச்சொற்கள், டோக்கன்கள் அல்லது API விசைகள் எப்போதுமே இருக்காது — புதிய தளத்தில் அவற்றை நீங்கள் மீண்டும் உள்ளிட வேண்டும்.','Settings saved.'=>'அமைப்புகள் சேமிக்கப்பட்டன.','Every setting on this plugin is back to its default.'=>'இந்த செருகுநிரலில் உள்ள ஒவ்வொரு அமைப்பும் அதன் இயல்புநிலைக்குத் திரும்பியுள்ளது.','Done.'=>'முடிந்தது.','That action is not available.'=>'அந்தச் செயல் கிடைக்கவில்லை.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'அந்த கோப்பை படிக்க முடியவில்லை. Zinn® செருகுநிரலில் இருந்து ஏற்றுமதி செய்யப்பட்ட அமைப்புகளின் கோப்பைத் தேர்ந்தெடுக்கவும்.','That file is too large to be a settings export.'=>'அந்தக் கோப்பு அமைப்புகளின் ஏற்றுமதிக்கு மிகவும் பெரியது.','That file is not a Zinn® settings export.'=>'அந்தக் கோப்பு ஒரு Zinn® அமைப்புகளின் ஏற்றுமதி அல்ல.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'அந்தக் கோப்பு வேறு செருகுநிரலிலிருந்து (%s) ஏற்றுமதி செய்யப்பட்டது, எனவே அதை இங்கே இறக்குமதி செய்வது இந்தச் செருகுநிரலுக்குப் புரியாத அமைப்புகளைச் சேமிக்கும்.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d அமைப்பு இறக்குமதி செய்யப்பட்டது. கடவுச்சொற்கள் மற்றும் API விசைகள் ஒருபோதும் ஏற்றுமதியில் இருக்காது, எனவே அவற்றை மீண்டும் உள்ளிடவும்.' . "\0" . '%d அமைப்புகள் இறக்குமதி செய்யப்பட்டன. கடவுச்சொற்களும் API விசைகளும் ஒருபோதும் ஏற்றுமதியில் இருக்காது, எனவே அவற்றை மீண்டும் உள்ளிடவும்.','The archive would be %1$d MB, over the %2$d MB limit set on this site. Raise the limit, or exclude some folders, on the Zinn Digital® → Connector → Backups screen.'=>'இந்த காப்பகம் %1$d MB ஆக இருக்கும், இது இந்த தளத்தில் நிர்ணயிக்கப்பட்ட %2$d MB வரம்பை மீறுகிறது. Zinn Digital® → Connector → Backups திரையில் வரம்பை அதிகரிக்கவும் அல்லது சில கோப்புறைகளைத் தவிர்க்கவும்.','This site\'s PHP cannot create archives, so a backup could not be made.'=>'இந்தத் தளத்தின் PHP-ஆல் காப்பகங்களை உருவாக்க முடியாது, எனவே காப்புப்பிரதியை எடுக்க முடியவில்லை.','Could not create a temporary file.'=>'தற்காலிக கோப்பை உருவாக்க முடியவில்லை.','This site\'s files could not be archived.'=>'இந்தத் தளத்தின் கோப்புகளை காப்பகப்படுத்த முடியவில்லை.','This site\'s PHP cannot compress archives, so a backup could not be made.'=>'இந்தத் தளத்தின் PHP-ஆல் காப்பகங்களைச் சுருக்க முடியாது, எனவே காப்புப்பிரியை உருவாக்க முடியவில்லை.','A backup of this site needs about %1$s of temporary space and only %2$s is free, so it was not attempted.'=>'இந்தத் தளத்தின் காப்புப்பிரதிக்கு தோராயமாக %1$s தற்காலிக இடம் தேவைப்படுகிறது மற்றும் %2$s மட்டுமே காலியாக உள்ளது, எனவே அது முயற்சிக்கப்படவில்லை.','This WordPress user cannot publish posts, so a connection made now could not publish either. Sign in as a user who can, and try again.'=>'இந்த WordPress பயனரால் பதிவுகளை வெளியிட முடியாது, எனவே இப்போது உருவாக்கப்பட்ட இணைப்பினாலும் வெளியிட முடியாது. வெளியிடக்கூடிய பயனராக உள்நுழைந்து, மீண்டும் முயற்சிக்கவும்.','Application passwords are turned off on this site, so we cannot create a credential. Ask your host to enable them, or connect the site with a password you create yourself in your Zinn Digital® dashboard.'=>'இந்தத் தளத்தில் பயன்பாட்டுக் கடவுச்சொற்கள் முடக்கப்பட்டுள்ளன, எனவே எங்களால் சான்றளிப்பை உருவாக்க முடியாது. அவற்றை இயக்க உங்கள் ஹோஸ்டை கேட்கவும் அல்லது உங்கள் Zinn Digital® டாஷ்போர்டில் நீங்களே உருவாக்கும் கடவுச்சொல் மூலம் தளத்தை இணைக்கவும்.','WordPress would not create a credential for this site. Nothing has been sent anywhere.'=>'இந்தத் தளத்திற்கான நற்சான்றிதழை WordPress-ஆல் உருவாக்க முடியவில்லை. எங்குமே எதுவும் அனுப்பப்படவில்லை.','We could not reach Zinn Digital® from this site. Nothing was connected, and the credential we made has been removed. Check the site can make outgoing requests, and try again.'=>'இந்தத் தளத்திலிருந்து Zinn Digital®-ஐ அணுக முடியவில்லை. எதுவும் இணைக்கப்படவில்லை, மேலும் நாங்கள் உருவாக்கிய நற்சான்று அகற்றப்பட்டது. தளம் வெளிச்செல்லும் கோரிக்கைகளைச் செய்ய முடியுமா என்பதைச் சரிபார்த்து, மீண்டும் முயற்சிக்கவும்.','Zinn Digital® did not accept that pairing code. Nothing was connected. Generate a fresh code in your dashboard and try again.'=>'Zinn Digital® அந்த இணைப்புக் குறியீட்டை ஏற்றுக்கொள்ளவில்லை. எதுவும் இணைக்கப்படவில்லை. உங்கள் டாஷ்போர்டில் புதிய குறியீட்டை உருவாக்கி மீண்டும் முயற்சிக்கவும்.','Connected. Zinn Digital® can now publish to this site.'=>'இணைக்கப்பட்டுள்ளது. Zinn Digital® இப்போது இந்த தளத்தில் வெளியிட முடியும்.','Connected'=>'இணைக்கப்பட்டுள்ளது','Connecting…'=>'இணைக்கிறது…','Connected, but something needs attention'=>'இணைக்கப்பட்டுள்ளது, ஆனால் எதையோ கவனிக்க வேண்டும்','Not connected'=>'இணைக்கப்படவில்லை','Running on your own account'=>'உங்கள் சொந்த கணக்கில் இயங்குகிறது','We could not check this'=>'இதைச் சரிபார்க்க முடியவில்லை','This plugin did not say why. Send a diagnostics report and we will look.'=>'இந்த செருகுநிரல் ஏன் என்று குறிப்பிடவில்லை. கண்டறிதல் அறிக்கையை அனுப்பவும், நாங்கள் பரிசீலிக்கிறோம்.','Connection status'=>'இணைப்பு நிலை','Last checked %s ago.'=>'கடைசியாக %s முன்பு சரிபார்க்கப்பட்டது.','(opens in a new tab)'=>'(புதிய தாவலில் திறக்கும்)','Send this to Zinn® support'=>'Zinn® ஆதரவுப் பிரிவுக்கு இதை அனுப்பவும்','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'இதுதான் சரியாக அனுப்பப்படும் — வேறு எதுவும் இல்லை, மறைக்கப்பட்டதும் இல்லை. உங்கள் கடவுச்சொற்கள், டோக்கன்கள் மற்றும் API விசைகள் இதில் இல்லை.','The diagnostics report that will be sent'=>'அனுப்பப்படவுள்ள கண்டறிதல் அறிக்கை','Copy to clipboard'=>'கிளிப் போர்டுக்கு நகலெடு','Send this report to Zinn® support'=>'இந்த அறிக்கையை Zinn® ஆதரவுக் குழுவிற்கு அனுப்பவும்','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'நாங்கள் உங்களுக்காக ஒரு ஆதரவுச் சீட்டைத் திறந்து மின்னஞ்சல் மூலம் பதிலளிப்போம். நீங்கள் அதை அனுப்ப விரும்பவில்லை என்றால், மேலே உள்ளதை நகலெடுத்து நீங்களே ஒரு சீட்டில் ஒட்டவும்.','Copied'=>'நகலெடுக்கப்பட்டது','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'இந்தச் சேவையகத்திலிருந்து (%s) Zinn Digital®-ஐ எங்களால் அடைய முடியவில்லை. மேலே உள்ள அறிக்கையை நகலெடுத்து அதற்குப் பதிலாக ஒரு டிக்கெட்டைத் திறக்கவும் — உங்கள் அமைப்புகளில் எதுவும் தவறில்லை.','Sent. Zinn® support has your report and will reply by email.'=>'Zinn® ஆதரவு உங்கள் அறிக்கையைப் பெற்றுள்ளது, மேலும் மின்னஞ்சல் மூலம் பதிலளிக்கும்.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Zinn® ஆதரவு உங்கள் அறிக்கையைப் பெற்றுள்ளது — குறிப்பு %s — மேலும் மின்னஞ்சல் மூலம் பதிலளிக்கும்.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'குறுகிய காலத்தில் பல அறிக்கைகளை அனுப்பியுள்ளீர்கள். சில நிமிடங்கள் காத்திருந்து மீண்டும் முயற்சிக்கவும் — முந்தைய அறிக்கைகள் வந்து சேர்ந்துவிட்டன.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® அறிக்கையை இப்போதைக்கு ஏற்றுக்கொள்ள முடியவில்லை — இது எங்கள் தரப்பில் ஏற்பட்ட சிக்கல், உங்களுடையது அல்ல. சிறிது நேரம் கழித்து மீண்டும் முயற்சிக்கவும் அல்லது மேலே உள்ள அறிக்கையை ஒரு டிக்கெட்டில் நகலெடுக்கவும்.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'அறிக்கை நிராகரிக்கப்பட்டது (HTTP %d). அதை மேலே நகலெடுத்து, அந்த எண்ணைக் குறிப்பிட்டு ஒரு டிக்கெட்டைத் திறக்கவும்.','This site’s owner has turned off image uploads for Zinn Digital® in the Zinn® Connector settings.'=>'Zinn® கனெக்டர் அமைப்புகளில் Zinn Digital® க்கான பட பதிவேற்றங்களை இந்தத் தளத்தின் உரிமையாளர் முடக்கியுள்ளார்.','This site’s owner has turned off edits to existing articles for Zinn Digital® in the Zinn® Connector settings.'=>'Zinn Digital® இணைப்பி அமைப்புகளில் இந்தத் தளத்தின் உரிமையாளர் Zinn® கட்டுரைகளுக்கான திருத்தங்களை முடக்கியுள்ளார்.','New article on your site: %s'=>'உங்கள் தளத்தில் புதிய கட்டுரை: %s','Zinn Digital® has added an article to your site.

Title: %1$s
Edit it: %2$s
Status: %3$s

Turn these emails off on the Zinn Digital® → Connector → Publishing screen.'=>'Zinn Digital® உங்கள் தளத்தில் ஒரு கட்டுரையைச் சேர்த்துள்ளது.

தலைப்பு: %1$s
இதைத் திருத்தவும்: %2$s
நிலை: %3$s

Zinn Digital® → Connector → Publishing திரையில் இந்த மின்னஞ்சல்களை முடக்கிவிடலாம்.','%s — guides and services'=>'%s — வழிகாட்டிகளும் சேவைகளும்','User guides'=>'பயனர் வழிகாட்டிகள்','Read the %s user guide'=>'%s பயனர் வழிகாட்டியைப் படிக்கவும்','Hide this'=>'ம_ மறைக்கவும்','Zinn® hosting for WordPress'=>'வேர்ட்பிரஸ் (WordPress)-க்கான Zinn® ஹோஸ்டிங்','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, தினசரி காப்புப்பிரதிகள், இலவச இடம்பெயர்வு மற்றும் ஒன்றுக்கும் மேற்பட்ட தளங்களை இயக்குபவர்களுக்காக உருவாக்கப்பட்ட கட்டுப்பாட்டுப் பலகம்.','The Zinn® marketplace'=>'The Zinn® அங்காடி','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'நிறுவப்பட்ட தளங்கள், டொமைன்கள் மற்றும் இணைப்பு இடங்களை வாங்கவும் விற்கவும், இரு தரப்பினரும் திருப்தி அடையும் வரை பணம் பாதுகாப்பாகப் பிடிக்கப்படும்.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — இதற்காகவே வேலை செய்பவர்களை பணியமர்த்துங்கள்','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'எங்களது உலகளாவிய ஃப்ரீலான்ஸ் சந்தை: எழுத்தாளர்கள், வடிவமைப்பாளர்கள், டெவலப்பர்கள் மற்றும் எஸ்சிஓ நிபுணர்களின் 10,000-க்கும் மேற்பட்ட ரெடிமேட் சேவைகளை உலவுங்கள், அல்லது ஒரு திட்டத்தைப் பதிவிட்டு அவர்களை ஏலம் எடுக்கச் சொல்லுங்கள்.','Connector'=>'இணைப்பான்','Connection'=>'இணைப்பு','Publishing'=>'வெளியிடுகிறது','Backups'=>'காப்புப்பிரதிகள்','Advanced'=>'மேம்பட்ட','Check the connection now'=>'இணைப்பை இப்போது சரிபார்க்கவும்','Disconnect this site'=>'இந்தத் தளத்தைத் துண்டிக்குக','This revokes the credential Zinn Digital® uses, so we can no longer publish to this site. Anything already published stays. Continue?'=>'இது Zinn Digital® பயன்படுத்தும் நற்சான்றிதழை ரத்து செய்கிறது, எனவே எங்களால் இனி இந்தத் தளத்தில் வெளியிட முடியாது. ஏற்கனவே வெளியிடப்பட்டவை அப்படியே இருக்கும். தொடரவா?','What we may do on this site'=>'இந்தத் தளத்தில் நாங்கள் என்ன செய்யக்கூடும்','The credential we hold is an ordinary WordPress application password, so WordPress itself decides what is possible. These narrow it further, on your side.'=>'நாங்கள் வைத்திருக்கும் நற்சான்றிதழ் சாதாரண WordPress அப்ளிகேஷன் கடவுச்சொல் ஆகும், எனவே என்ன சாத்தியம் என்பதை WordPress-ஆ கவே முடிவு செய்யப்படுகிறது. உங்கள் தரப்பில் உள்ள இவை மேலும் வரம்புக்குட்படுத்துகின்றன.','Publish articles as'=>'கட்டுரைகளை இப்படி வெளியிடவும்','Choose “a draft” if you would rather read everything before it goes live.'=>'எல்லாவற்றையும் நேரலையில் வெளியிடுவதற்கு முன்பு நீங்களே படித்துப் பார்க்க விரும்பினால் “ஒரு வரைவு” (a draft) என்பதைத் தேர்ந்தெடுக்கவும்.','Published straight away'=>'உடனடியாக வெளியிடப்பட்டது','A draft, for me to review'=>'நான் சரிபார்க்க ஒரு வரைவு','Pending review'=>'மதிப்பாய்வு நிலுவையில் உள்ளது','Scheduled, using the date we send'=>'திட்டமிடப்பட்டது, நாங்கள் அனுப்பும் தேதியைப் பயன்படுத்தி','Show the author as'=>'ஆசிரியரைக் காட்டுக','Which of your users appears as the author. This does not change who we sign in as.'=>'உங்கள் பயனர்களில் யார் ஆசிரியராகக் காட்டப்படுகிறார்கள். இது நாங்கள் யாருடன் உள்நுழைகிறோம் என்பதை மாற்றாது.','Put articles in'=>'கட்டுரைகளைச் சேர்','Allow images'=>'படங்களை அனுமதிக்கவும்','Let Zinn Digital® upload images into this site’s media library'=>'இந்தத் தளத்தின் மீடியா நூலகத்திற்குப் படங்களைப் பதிவேற்ற Zinn Digital®-ஐ அனுமதிக்கவும்','Turn this off and articles arrive without their images. Nothing already uploaded is removed.'=>'இதை முடக்கிவிட்டால் கட்டுரைகள் படங்களுடன் வராது. ஏற்கனவே பதிவேற்றிய எதுவும் அகற்றப்படாது.','Allow edits'=>'திருத்தங்களை அனுமதிக்கவும்','Let Zinn Digital® update an article it published before'=>'Zinn Digital® முன்பு வெளியிட்ட ஒரு கட்டுரையைப் புதுப்பிக்க அனுமதிக்கவும்','Used for corrections and re-optimisation. It never touches anything you wrote yourself.'=>'திருத்தங்களுக்கும் மீள்-உகப்பாக்கத்திற்கும் பயன்படுத்தப்படுகிறது. இது நீங்கள் எழுதிய எதையும் ஒருபோதும் தொடாது.','Tell me when something is published'=>'ஏதாவது வெளியிடப்படும் போது எனக்குத் தெரிவிக்கவும்','Leave blank for no email. One message per article, from your own site.'=>'மின்னஞ்சல் தேவையில்லை என்றால் காலியாக விடவும். ஒவ்வொரு கட்டுரைக்கும் உங்கள் சொந்த தளத்திலிருந்து ஒரு செய்தி அனுப்பப்படும்.','Off-site backups'=>'வெளியிட காப்புப்பிரதிகள்','This site sends its own backup straight to Zinn® storage. Nothing passes through our servers on the way.'=>'இந்த தளம் தனது சொந்த காப்புப்பிரதியை நேராக Zinn® சேமிப்பகத்திற்கு அனுப்புகிறது. இடையில் எங்கள் சேவையகங்கள் வழியாக எதுவும் செல்வதில்லை.','Back this site up to Zinn Digital®'=>'இந்தத் தளத்தை Zinn Digital® இல் காப்புப் பிரதி எடுக்கவும்','Backup token'=>'காப்புப் பிரதி டோக்கன்','Set for you when the site was connected. You will only need to touch this if support asks.'=>'தளம் இணைக்கப்பட்டபோது உங்களுக்காக அமைக்கப்பட்டது. ஆதரவுக் குழு கேட்டால் மட்டுமே இதை மாற்ற வேண்டும்.','Leave these out'=>'இவற்றைத் தவிர்க்கவும்','One path per line, relative to wp-content — for example <code>cache</code> or <code>uploads/backups</code>. Caches and other backup plugins’ folders are the usual candidates.'=>'வரிக்கு ஒரு பாதை, wp-content-க்கு சார்பாக - உதாரணமாக <code>cache</code> அல்லது <code>uploads/backups</code>. தற்காலிக நினைவகங்கள் (Caches) மற்றும் பிற காப்புப்பிரதி செருகுநிரல்களின் கோப்புறைகள் பொதுவாக இதற்குப் பொருத்தமானவை.','Stop if the archive would exceed'=>'காப்பகம் வரம்பை தாண்டினால் நிறுத்தவும்','Megabytes. A shared host will usually kill a very large archive part-way; a bound turns that into a message instead of a silent failure.'=>'மெகாபைட்கள். பகிரப்பட்ட ஹோஸ்ட் பொதுவாக மிகவும் பெரிய காப்பகத்தை நடுவழியில் நிறுத்திவிடும்; அமைப்பானது அதை அமைதியான தோல்வியாக மாற்றாமல் ஒரு செய்தியாக மாற்றும்.','Detailed logging'=>'விரிவான பதிவு செய்தல்','Record what this plugin does, for support'=>'ஆதரவிற்காக, இந்தப் செருகுநிரல் என்ன செய்கிறது என்பதைப் பதிவு செய்யவும்','Kept on this site, capped at the last 50 entries, and included in a diagnostics report. Turn it on before reproducing a problem.'=>'இந்தத் தளத்தில் வைக்கப்படும், கடைசி 50 பதிவுகளுடன் வரம்பிடப்படும், மேலும் கண்டறிதல் அறிக்கையில் சேர்க்கப்படும். ஒரு சிக்கலை மீண்டும் உருவாக்குவதற்கு முன்பு அதை இயக்கவும்.','On uninstall'=>'நிறுவல் நீக்கும்போது','Delete this plugin’s settings when it is uninstalled'=>'இந்த செருகுநிரல் (plugin) நிறுவல் நீக்கப்படும்போது அதன் அமைப்புகளை நீக்கவும்','Uninstalling never revokes the application password — that is deliberate, so uninstalling to try something else does not break your publishing. Use Disconnect above if you want the credential gone.'=>'செயலியை நீக்குவது பயன்பாட்டு கடவுச்சொல்லை ஒருபோதும் ரத்து செய்யாது — இது வேண்டுமென்றே செய்யப்பட்டது, எனவே வேறு ஒன்றை முயற்சிக்க நீக்குவது உங்கள் வெளியீட்டை முடக்காது. நற்சான்றிதழ் நீக்கப்பட வேண்டுமெனில் மேலே உள்ள துண்டி என்பதைப் பயன்படுத்தவும்.','The user we sign in as'=>'நாங்கள் உள்நுழையும் பயனர்','The site’s default category'=>'தளத்தின் இயல்புநிலை வகை','Connect this site again'=>'இந்தத் தளத்தை மீண்டும் இணைக்கவும்','Connect this site'=>'இந்தத் தளத்தை இணைக்கவும்','Open your Zinn Digital® dashboard, go to Content → Other sites, and press “Get a pairing code”. Paste it below.'=>'உங்கள் Zinn Digital® டாஷ்போர்டைத் திறந்து, உள்ளடக்கம் (Content) → பிற தளங்கள் (Other sites) என்பதற்குச் சென்று, “Get a pairing code” என்பதை அழுத்தவும். அதை கீழே ஒட்டவும்.','Connecting again creates a fresh credential and leaves the old one in place — use Disconnect first if you want the old one gone.'=>'மீண்டும் இணைப்பது புதிய நற்சான்றை உருவாக்குகிறது மற்றும் பழையதை அப்படியே விட்டுவிடுகிறது — பழையது அகற்றப்பட வேண்டுமெனில் முதலில் துண்டி (Disconnect) என்பதைப் பயன்படுத்தவும்.','Pairing code'=>'இணைப்புக் குறியீடு','It expires thirty minutes after you generate it, and can only be used once.'=>'இது நீங்கள் உருவாக்கிய முப்பது நிமிடங்களுக்குப் பிறகு காலாவதியாகும், மேலும் ஒரு முறை மட்டுமே பயன்படுத்த முடியும்.','You are not allowed to connect this site.'=>'இந்தத் தளத்தை இணைக்க உங்களுக்கு அனுமதி இல்லை.','This site is not connected to Zinn Digital®.'=>'இந்த தளம் Zinn Digital® உடன் இணைக்கப்படவில்லை.','Nothing is wrong — it has simply not been paired yet. Get a pairing code from your Zinn® dashboard and paste it below.'=>'எதுவும் தவறாகவில்லை — அது இன்னும் இணைக்கப்படவில்லை. உங்கள் Zinn® டேஷ்போர்டிலிருந்து இணைப்புக் குறியீட்டைப் பெற்று, அதை கீழே ஒட்டவும்.','Open my Zinn® dashboard'=>'எனது Zinn® கட்டுப்பாட்டுப் பலகத்தைத் திறக்கவும்','The connection is broken.'=>'இணைப்பு துண்டிக்கப்பட்டுள்ளது.','The WordPress user the credential belonged to (%s) no longer exists on this site, so nothing we send can be published. Connect again as a user who can publish.'=>'இந்த நற்சான்றுக்குச் சொந்தமான WordPress பயனர் (%s) இனி இந்தத் தளத்தில் இல்லை, எனவே நாங்கள் அனுப்பும் எதையும் வெளியிட முடியாது. வெளியிடக்கூடிய பயனராக மீண்டும் இணைக்கவும்.','The “Zinn Digital® (publishing)” application password has been deleted from this site, so we can no longer sign in. Connect again to create a new one — nothing else was lost.'=>'இந்த தளத்திலிருந்து “Zinn Digital® (publishing)” பயன்பாட்டுச் கடவுச்சொல் நீக்கப்பட்டுவிட்டது, எனவே எங்களால் இனி உள்நுழைக்க முடியாது. புதிய ஒன்றை உருவாக்க மீண்டும் இணைக்கவும் — வேறு எதுவும் இழக்கப்படவில்லை.','See this site’s application passwords'=>'இந்தத் தளத்தின் பயன்பாட்டு கடவுச்சொற்களைக் காண்க','Connected, but publishing would fail.'=>'இணைக்கப்பட்டுள்ளது, ஆனால் வெளியிடுவது தோல்வியடையும்.','The credential belongs to %s, and that user can no longer publish posts. Sign-in still works, so nothing looks wrong until an article is due. Give that user the ability to publish, or connect again as somebody who can.'=>'இந்த நற்சான்று %s என்பவருக்குச் சொந்தமானது, அந்த பயனர் இனி பதிவுகளை வெளியிட முடியாது. உள்நுழைவு தொடர்ந்து செயல்படுகிறது, எனவே ஒரு கட்டுரை வெளியிடும் நேரம் வரும் வரை எதுவும் தவறாகத் தெரியாது. அந்த பயனர் வெளியிடும் திறனை வழங்குங்கள், அல்லது அவ்வாறு செய்யக்கூடிய வேறு யாராகவேனும் மீண்டும் இணைக்கவும்.','Edit that user'=>'அந்த பயனரைத் திருத்துக','Connected here — we could not reach Zinn Digital® to confirm.'=>'இணைக்கப்பட்டுள்ளது — உறுதிப்படுத்த எங்களால் Zinn Digital® ஐ அடைய முடியவில்லை.','Connected, but your Zinn® account needs attention.'=>'இணைக்கப்பட்டுள்ளது, ஆனால் உங்களது Zinn® கணக்கிற்கு கவனம் தேவை.','Connected to Zinn Digital®.'=>'Zinn Digital® உடன் இணைக்கப்பட்டுள்ளது.','Connected to Zinn Digital® as %s.'=>'%s ஆக Zinn Digital® உடன் இணைக்கப்பட்டுள்ளது.','Publishing as'=>'வெளியிடும் முறை','Zinn® site ID'=>'Zinn® தள ஐடி','This server could not reach api.zinndigital.com (%s). That is usually a firewall or an outbound-connection rule on your host, not a problem with your Zinn® account — publishing may still be working.'=>'இந்த சேவையகத்தால் api.zinndigital.com (%s) ஐ அடைய முடியவில்லை. இது பொதுவாக ஃபயர்வால் அல்லது உங்கள் ஹோஸ்டில் உள்ள வெளிச்செல்லும் இணைப்பு விதியாகும், உங்கள் Zinn® கணக்கில் உள்ள சிக்கல் அல்ல — வெளியிடுதல் இன்னும் செயல்படக்கூடும்.','Zinn Digital® answered with an error of its own — that is our end, not yours. Publishing is unaffected while this clears.'=>'Zinn Digital® அதன் சொந்த பிழையுடன் பதிலளித்தது — அது உங்கள் முடிவு அல்ல, எங்கள் முடிவு. இது சரியாகும் வரை வெளியீடு பாதிக்கப்படாது.','Your Zinn® account is not currently able to publish to this site. Your dashboard says why.'=>'உங்கள் Zinn® கணக்கு தற்போது இந்தத் தளத்தில் வெளியிட இயலாத நிலையில் உள்ளது. உங்கள் டாஷ்போர்டு அதற்கான காரணத்தைக் கூறுகிறது.','Zinn Digital® answered HTTP %d, which we do not recognise. Send a diagnostics report from the Support tab and we will look — do not change anything here first.'=>'Zinn Digital® HTTP %dஐ அளித்தது, அதை நாங்கள் அடையாளம் காணவில்லை. ஆதரவு (Support) தாவலில் இருந்து கண்டறிதல் அறிக்கையை அனுப்பவும், நாங்கள் பார்க்கிறோம் — முதலில் இங்கே எதையும் மாற்ற வேண்டாம்.','Check again now'=>'இப்போது மீண்டும் சரிபார்க்கவும்','Checked. The connection is live.'=>'சோதிக்கப்பட்டது. இணைப்பு செயல்பாட்டில் உள்ளது.','We could not remove the application password, so this site is still connected. Delete “Zinn Digital® (publishing)” on your profile screen and try again — we have changed nothing.'=>'செயலி கடவுச்சொல்லை எங்களால் நீக்க முடியவில்லை, எனவே இந்தத் தளம் இன்னும் இணைக்கப்பட்டுள்ளது. உங்கள் சுயவிவரத் திரையில் உள்ள “Zinn Digital® (publishing)” என்பதை நீக்கிவிட்டு மீண்டும் முயற்சிக்கவும் — நாங்கள் எதையும் மாற்றவில்லை.','Disconnected. The application password has been revoked, so Zinn Digital® can no longer publish to this site. Nothing already published was touched.'=>'துண்டிக்கப்பட்டது. பயன்பாட்டுச் கடவுச்சொல் திரும்பப் பெறப்பட்டுவிட்டது, எனவே Zinn Digital® நிறுவனத்தால் இனி இந்தத் தளத்தில் வெளியிட முடியாது. ஏற்கனவே வெளியிடப்பட்ட எதிலும் மாற்றம் செய்யப்படவில்லை.','That file could not be read from this server, so nothing was uploaded.'=>'இந்தச் சேவையகத்திலிருந்து அந்தக் கோப்பைப் படிக்க முடியவில்லை, எனவே எதுவும் பதிவேற்றப்படவில்லை.','This site could not stream the upload, so nothing was sent.'=>'இந்த தளம் பதிவேற்றத்தை ஸ்ட்ரீம் செய்ய முடியவில்லை, எனவே எதுவும் அனுப்பப்படவில்லை.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'இந்தக் கோப்பு %1$s ஆகும், மேலும் இந்தத் தளத்தின் PHP-ல் cURL இல்லை, எனவே இதனால் பதிவேற்றக்கூடிய அதிகபட்ச அளவு %2$s ஆகும்.','The upload could not be completed.'=>'பதிவேற்றத்தை முடிக்க முடியவில்லை.','Storage refused the upload (HTTP %d).'=>'சேமிப்பிடம் பதிவேற்றத்தை மறுத்துவிட்டது (HTTP %d).','Style preset'=>'பாணி முன்னமைவு','A starting point. Anything below overrides it.'=>'ஒரு தொடக்கப் புள்ளி. கீழே உள்ளவை எவையும் இதை மீறும்.','Use my own colours and sizes'=>'எனது சொந்த வண்ணங்களையும் அளவுகளையும் பயன்படுத்துக','Leave this off and the preset is used exactly as it is.'=>'இதை முடக்கி விடுங்கள், மேலும் முன்னமைவு அப்படியே பயன்படுத்தப்படும்.','See the Zinn Digital® release notes.'=>'Zinn Digital® வெளியீட்டு குறிப்புகளைப் பார்க்கவும்.','The downloaded update failed its integrity check and was not installed.'=>'பதிவிறக்கம் செய்யப்பட்ட புதுப்பிப்பு அதன் ஒருமைமைச் சோதனையில் தோல்வியுற்றது மற்றும் நிறுவப்படவில்லை.']];